import{_ as a,c as t,o as r,ae as i}from"./chunks/framework.BtEkjhVd.js";const u=JSON.parse('{"title":"Architecture Decision Record 3: Use Tailwind, Shoelace and pure CSS 3 for Styling Support","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr-choose-styling-library/adr3.md","filePath":"architecture/adr-choose-styling-library/adr3.md"}'),o={name:"architecture/adr-choose-styling-library/adr3.md"};function n(s,e,l,c,h,p){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="architecture-decision-record-3-use-tailwind-shoelace-and-pure-css-3-for-styling-support" tabindex="-1">Architecture Decision Record 3: Use Tailwind, Shoelace and pure CSS 3 for Styling Support <a class="header-anchor" href="#architecture-decision-record-3-use-tailwind-shoelace-and-pure-css-3-for-styling-support" aria-label="Permalink to &quot;Architecture Decision Record 3: Use Tailwind, Shoelace and pure CSS 3 for Styling Support&quot;">​</a></h1><p>Date: 24/09/2024</p><h1 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h1><p>We are building the fAIr website that requires a responsive and customizable user interface. The stying must be consistent and modern, ensuring a great user experience. The development team has experience using custom CSS but wants to explore CSS frameworks that can save time and effort. We are looking for a framework that is easy to use, customizable, has a large community for support and has a compatible license with HOT.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><p>Easy to use: We want a framework that is simple to learn and can be integrated into our development workflow.</p></li><li><p>Customizable: We want a framework that can be customized to match the HOT brand guidelines and theme.</p></li><li><p>Large community support: We want a framework that has an active community of developers, libraries, and designers that can provide help and resources when needed.</p></li><li><p>Time-saving: We want a framework that can save time and effort in styling the UI.</p></li><li><p>License: We want a framework that is open source and compatible with HOT licensing requirement.</p></li><li><p>Size &amp; Performance: We want a framework that ships small CSS to the client, and would not bloat the website.</p></li><li><p>Future proof: Aligns with the future requirements of HOT tools in the long run.</p></li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><p><a href="https://getbootstrap.com/" target="_blank" rel="noreferrer">Bootstrap</a>: A popular CSS framework with a lot of pre-built components and a large community of developers.</p></li><li><p><a href="https://mui.com/material-ui/" target="_blank" rel="noreferrer">Material UI</a>: A CSS framework based on Google&#39;s Material Design language with pre-built components for UI development.</p></li><li><p><a href="https://v2.chakra-ui.com/" target="_blank" rel="noreferrer">Chakra UI</a>: Create accessible React apps with speed.</p></li><li><p><a href="https://sass-lang.com/" target="_blank" rel="noreferrer">SCSS</a>: CSS with superpowers.</p></li><li><p><a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a>: A utility-first CSS framework with a focus on customization and efficiency.</p></li><li><p><a href="https://shoelace.style/" target="_blank" rel="noreferrer">Shoelace</a>: A forward-thinking library of web components.</p></li></ul><h1 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h1><p>We&#39;ve chosen to use Tailwind CSS, CSS3 and Shoelace to support the development of the platform because of the strict timeline and for future flexibility. Shoelace components (and sometimes HOT UI component (e.g Tracking/Cookie banner)) will be used extensively because it aligns with the future requirements of <a href="https://github.com/hotosm/ui" target="_blank" rel="noreferrer">HOT UI</a>. Tailwind will be used occassionally in layout design and CSS3 via CSS modules will be used to support the designs when necessary.</p><p>These three offer flexibility, speed of development, and also in tune with future requirements.</p><h1 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h1><p>Approved.</p><h1 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h1><p>Nil.</p>',15)]))}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
